<template>
	<view class="container">
		<u-loading-page :loading="true" v-if="load" fontSize="28rpx" />
		<block v-else>
			<view class="inner">
				<scroll-view scroll-y class="cate-scroll">
					<view class="cate-items">
						<view class="cate-item" @click="cateClick(item)" :class="{'act':item.id==cat_id_1}" v-for="(item,index) in cate_list" :key="index">{{item.name}}</view>
					</view>
				</scroll-view>
				<view class="cate-right">
					<scroll-view scroll-x class="top-scroll">
						<view class="fl-items">
							<view class="fl-item" @click="cate2Click(item)" :class="{'act':item.id == cat_id_2}" v-for="(item,index) in cate_list2" :key="index">{{item.name}}</view>
						</view>
					</scroll-view>
					<scroll-view scroll-y="true" class="goods-scroll" @scrolltolower="loadMore">
						<block v-if="lists.length>0">
						<view class="goods">
							<view class="goods-item" v-for="(item,index) in lists" :key="index"  @click="toNext(`/pages/index/goods-detail?goods_id=${item.goods_id}`)">
								<image :src="item.goods_img" mode="aspectFill" class="goods-img"/>
								<view class="right">
									<view class="goods-name">{{item.goods_name}}</view>
									<view class="goods-bot">
										<view class="goods-price">
											<text class="fh-text">¥</text>
											<text class="price-text">{{item.goods_price}}</text>
										</view>
										<image @click.stop="join_cart1(item)" src="@/static/common/join-cart.png" class="cart-img" mode="widthFix"></image>
									</view>
								</view>
							</view>
						</view>
						<u-loadmore class="load-more" :status="hasMore?'loading':'nomore'" :nomoreText="noMore" />
						</block>
						<view class="empty-container" v-else>
							<u-empty text="暂无相关商品" :icon="emptyIcon" />
						</view>
					</scroll-view>
				</view>
			</view>
		</block>
		<wxLogin ref="wx_login" @loginAfter="loginAfter"></wxLogin>
	</view>
</template>

<script>
	import wxLogin from "@/components/wx-login/wx-login.vue"
	var _this;
	export default {
		data() {
			return {
				//导航栏高度
				navBarHeight: 44,
				statusbarH:10,
				navRight:0,
				cate_list: [],
				cate_list2: [],
				loginDisabled:false,
				loginShow:false,
				form:{
					pageIndex:1,
					pageSize:50,
					cate_id: 0,
				},
				cat_id_1:0,
				cat_id_2:0,
				cate_name:''
			};
		},
		methods: {
			loginAfter(result){
				console.log('loginAfter',result);
			},
			goNext(page){
				if (_this.user_id==0) {
					_this.loginShow = true
					return
				}
				_this.toNext(page)
			},
			loadMore(){
				if (_this.hasMore) {
					_this.form.pageIndex++
					_this.get_goods()
				}
			},
			cateClick(item){
				if (item.id == _this.cat_id_1) {
					return
				}
				_this.cat_id_1 = item.id
				_this.cat_id_2 = 0
				_this.form.pageIndex = 1
				_this.lists = []
				_this.get_cate_list2()
			},
			cate2Click(item){
				if (item.id == _this.cat_id_2) {
					return
				}
				_this.cat_id_2 = item.id
				_this.form.cate_id = item.id
				_this.form.pageIndex = 1
				_this.lists = []
				_this.get_goods()
			},
			async get_goods_category() {
				let params = {
					type:1,
				}
				const data = await _this.$post('port/get_goods_category',params)
				_this.cate_list = data.result.list
				if (_this.cat_id_1 == 0 && _this.cate_list.length > 0) {
					_this.cat_id_1 = _this.cate_list[0]['id']
				}
				if (_this.load) {
					_this.load = false
				}
				_this.get_cate_list2()
			},
			async get_cate_list2(){
				let params = {
					type:3,
					cate_id:_this.cat_id_1
				}
				const data = await _this.$post('port/get_goods_category',params)
				if(data.code==200){
					_this.cate_list2 = data.result.list
					if (_this.cat_id_2 == 0 && _this.cate_list2.length > 0) {
						_this.cat_id_2 = _this.cate_list2[0]['id']
						_this.form.cate_id = _this.cate_list2[0]['id']
					}
					_this.get_goods()
				}else{
				}
			},
			async get_goods(){
				const data = await _this.$post('port/goods_search_list',_this.form)
				if(data.code==200){
					_this.lists.push(...data.result.list)
					_this.hasMore=data.result.list.length>=_this.form.pageSize
				}else{
					_this.hasMore=false
				}
			},
			join_cart1(item){
				if (_this.user_id == 0) {
					_this.$refs.wx_login.loginShow = true
					return
				}
				_this.join_cart(item)
			}
		},
		onLoad(e) {
			_this = this;
			let sysInfo = uni.getSystemInfoSync();
			_this.statusbarH=sysInfo.statusBarHeight
			// #ifdef MP-WEIXIN
			// 胶囊信息
			let menu = uni.getMenuButtonBoundingClientRect();
			// 导航栏高度
			let navBarHeight = menu.height + 10;
			this.navBarHeight = navBarHeight
			_this.navRight = menu.width
			// #endif
			_this.get_goods_category()
		},
		onPullDownRefresh() {
			_this.form.pageIndex = 1
			_this.lists = []
			_this.get_goods_category()
			setTimeout(()=>{
				uni.stopPullDownRefresh()
			},1000)
		},
		components:{
			wxLogin
		},
	}
</script>

<style lang="scss" scoped>
	@import "static/css/goods.scss";
	$row-h:100rpx;
	.container {
		position: relative;
		height: 100%;
		.inner{
			height: 100%;
			@include flex-box();
		}
		.cate-scroll{
			width: 25%;
			height: 100%;
			.cate-items{
				.cate-item{
					height: $row-h;
					@include flex-box(row,center,center);
					position: relative;
					text-align: center;
					color: $text-2D2D2D;
					position: relative;
				}
				.act{
					color: #000;
					background: #fff;
					&::after{
						content: '';
						background: $bg-btn;
						height: 100%;
						width: 10rpx;
						position: absolute;
						left: 0;
						top: 0;
					}
				}
			}
		}
		.cate-right{
			width: 75%;
			height: 100%;
			background: #fff;
			.top-scroll{
				height: $row-h;
				white-space: nowrap;
				.fl-items{
					height: 100%;
					display: inline-flex;
					align-items: center;
					.fl-item{
						border-radius: 5rpx;
						padding:4rpx 18rpx;
						background: $bg-color;
						margin-left: 30rpx;
						border: 2rpx solid $bg-color;
						&.act{
							background: #F6FFF9;
							border-color: $bg-btn;
							color: $bg-btn;
						}
					}
				}
			}
			.goods-scroll{
				height: calc(100% - #{$row-h});
				.goods{
					padding: 0 30rpx;
					.goods-item{
						@include flex-box();
						.goods-img{
							width: 140rpx;
							height: 140rpx;
							border-radius: 10rpx;
							margin: 20rpx 20rpx 20rpx 0;
						}
						.right{
							padding: 20rpx 0;
							border-bottom: $global-border;
							flex: 1;
							display: flex;
							flex-direction: column;
							justify-content: space-around;
							.goods-name{}
							.goods-bot{
								@include flex-box(null,space-between,center);
								.goods-price{
									color: $text-theme;
									.price-text{
										margin-left: 5rpx;
										font-size: 32rpx;
									}
								}
								.cart-img{
									width: 40rpx;
								}
							}
						}
					}
				}
			}
		}
	}
</style>